import { DensityProvider, Label, Switch, useDensity } from "@wunderui/react"

function DensitySetting() {
  const { density, setDensity } = useDensity()
  return (
    <Label className="flex items-center gap-3">
      <Switch checked={density === "comfortable"} onCheckedChange={(on) => setDensity(on ? "comfortable" : "compact")} />
      Comfortable spacing
    </Label>
  )
}

export function App({ children }: { children: React.ReactNode }) {
  return <DensityProvider storageKey="wui-density">{children}</DensityProvider>
}

// app/layout.tsx
import { DensityProvider, densityScript } from "@wunderui/react"

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en" suppressHydrationWarning>
      <head>
        <script dangerouslySetInnerHTML={{ __html: densityScript() }} />
      </head>
      <body>
        <DensityProvider>{children}</DensityProvider>
      </body>
    </html>
  )
}

import { DensityProvider, useDensity } from "@wunderui/react"

export function Workspace({ profile, saveProfile, children }) {
  return (
    <DensityProvider
      density={profile.density}
      onDensityChange={(density) => saveProfile({ ...profile, density })}
      storageKey={false}
    >
      {children}
    </DensityProvider>
  )
}

function RowsPerPage() {
  const { density } = useDensity()
  return <span>{density === "comfortable" ? 10 : 15} rows per page</span>
}

import * as React from "react"
import { useScrollSpy } from "@wunderui/react"

const sections = ["overview", "billing", "members"]

export function SettingsPanel() {
  const box = React.useRef<HTMLDivElement>(null)
  const [active] = useScrollSpy(sections, box)
  return (
    <div className="flex gap-4">
      <nav aria-label="Sections" className="flex flex-col gap-1 text-sm">
        {sections.map((id) => (
          <a key={id} href={`#${id}`} aria-current={active === id ? "location" : undefined} className={active === id ? "font-medium text-foreground" : "text-text-secondary"}>
            {id}
          </a>
        ))}
      </nav>
      <div ref={box} className="h-48 overflow-y-auto">
        {sections.map((id) => (
          <section key={id} id={id} className="min-h-40">…</section>
        ))}
      </div>
    </div>
  )
}

import { useScrollSpy } from "@wunderui/react"

const headings = ["introduction", "installation", "usage", "api"]

export function ArticleNav() {
  const [active] = useScrollSpy(headings)
  return (
    <nav aria-label="On this page" className="sticky top-24 flex flex-col gap-1 text-sm">
      {headings.map((id) => (
        <a key={id} href={`#${id}`} aria-current={active === id ? "location" : undefined}>
          {id}
        </a>
      ))}
    </nav>
  )
}

