import { Button, Input, Label, useToast } from "@wunderui/react"

export function ProfileForm() {
  const toast = useToast()
  return (
    <form
      onSubmit={(event) => {
        event.preventDefault()
        toast.add({ title: "Changes saved", description: "Your profile is up to date.", type: "success" })
      }}
    >
      <Label htmlFor="name">Display name</Label>
      <Input id="name" defaultValue="Nora Lindgren" />
      <Button type="submit" variant="plain">Save changes</Button>
    </form>
  )
}

const toast = useToast()

async function exportReport() {
  await toast.promise(createExport(), {
    loading: { title: "Preparing the export…" },
    success: { title: "Export ready", type: "success" },
    error: { title: "The export failed", description: "Try again in a minute.", type: "error" },
  })
}

const toast = useToast()

async function uploadReport(file: File) {
  const id = toast.add({ title: `Uploading ${file.name}…`, timeout: 0 })
  await upload(file)
  toast.update(id, { title: `${file.name} uploaded`, type: "success", timeout: 5000 })
}

